mapper.insert:
insert into audit_event (
    aggregate_type, aggregate_id, action, result_status,
    actor_user_id, actor_name, detail_json, occurred_at
) values (
    #{aggregateType}, #{aggregateId}, #{action}, #{resultStatus},
    #{actorUserId}, #{actorName}, cast(#{detailJson} as json), #{occurredAt}
)

mapper.select:
select count(1)
from audit_event
where aggregate_type = #{aggregateType}
  and occurred_at >= #{from}
  and occurred_at < #{to}
